    "Avoid major financial decisions today. Saturn casts a cautionary aspect — wait until Thursday for investments.": "ఈరోజు పెద్ద ఆర్థిక నిర్ణయాలు తీసుకోకండి. శని ప్రభావం వల్ల పెట్టుబడులకు గురువారం వరకు వేచి ఉండండి.",
    "Recite Lakshmi Stotra in the morning": "ఉదయం లక్ష్మీ స్తోత్రం పఠించండి",
    "Your vitality is strong. The Sun in your 6th house supports physical health. Morning exercise will be especially beneficial.": "మీ శక్తి మరియు ఉత్సాహం బాగుంది. 6వ స్థానంలో సూర్యుడు ఆరోగ్యానికి రక్షణనిస్తాడు. ఉదయం వ్యాయామం మేలు చేస్తుంది.",
    "Drink saffron milk at night for better sleep": "మంచి నిద్ర కోసం రాత్రి కుంకుమపువ్వు పాలు తాగండి",
