    "Ancient wisdom through sacred cards": "పవిత్ర కార్డ్స్ ద్వారా ప్రాచీన దివ్య మార్గదర్శకత్వం",
    "Tarot is a powerful divination tool that uses 78 symbolic cards to reveal hidden truths, illuminate life paths, and provide guidance on love, career, and spiritual growth. Each card carries profound archetypal wisdom.": "టారో అనేది 78 పవిత్ర చిహ్నాల కార్డులతో కూడిన శక్తివంతమైన భవిష్యత్ దర్శనం. ఇది దాగి ఉన్న సత్యాలను ఆవిష్కరిస్తూ ప్రేమ, కెరీర్ మరియు ఆధ్యాత్మిక వృద్ధికి మార్గదర్శనం చేస్తుంది.",
    "Daily Card Draw": "నేటి టారో కార్డ్",
    "Your Card of the Day": "మీ నేటి ప్రత్యేక కార్డ్",
    "The Star": "ది స్టార్ (The Star)",
    "Hope, faith, purpose, renewal, and spirituality. A period of calm after a storm — trust in the universe's plan.": "ఆశ, విశ్వాసం, పునరుజ్జీవనం మరియు ఆధ్యాత్మిక ప్రశాంతత. తుఫాను ముగిసిన తర్వాత వెల్లివిరిసే ప్రశాంతత — విశ్వ సంకల్పాన్ని నమ్మండి.",
    "Reading Types": "రీడింగ్ రకాలు",
    "Love & Relationship Spread": "ప్రేమ & సంబంధాల స్ప్రెడ్",
    "A 5-card spread revealing the current state of your love life, obstacles, and the path forward.": "ప్రేమ జీవిత స్థితి, ఎదురయ్యే అడ్డంకులు మరియు భవిష్యత్ మార్గాన్ని తెలిపే 5 కార్డ్స్ స్ప్రెడ్.",
    "Career & Finance Spread": "కెరీర్ & ఆర్థిక స్ప్రెడ్",
    "A 3-card spread covering your current career situation, challenges, and the best action to take.": "ప్రస్తుత ఉద్యోగ స్థితి, సవాళ్లు మరియు తీసుకోవాల్సిన నిర్ణయాలను తెలిపే 3 కార్డ్స్ స్ప్రెడ్.",
    "Celtic Cross Spread": "సెల్టిక్ క్రాస్ సమగ్ర స్ప్రెడ్",
    "The most comprehensive 10-card spread providing a complete overview of your life situation.": "జీవితంలోని అన్ని అంశాలను సమగ్రంగా విశ్లేషించే 10 కార్డ్స్ సెల్టిక్ క్రాస్ స్ప్రెడ్.",
    "Major Arcana Cards": "మేజర్ అర్కానా కార్డ్స్",
    "The Fool": "ది ఫూల్ (The Fool)",
    "The Magician": "ది మెజీషియన్ (The Magician)",
