    "The Chariot": "ది ఛారియట్ (The Chariot)",
    "Decode the numbers of your destiny": "మీ పుట్టిన తేదీలోని సంఖ్యా రహస్యాలను తెలుసుకోండి",
    "Numerology is the ancient science of numbers and their divine influence on human life. Every number carries a unique vibration that shapes your personality, destiny, and life path.": "సంఖ్యాశాస్త్రం అనేది సంఖ్యల వెనుక ఉన్న దైవిక శక్తుల ప్రాచీన విజ్ఞానం. ప్రతి సంఖ్యకు మీ వ్యక్తిత్వాన్ని, భవిష్యత్తును ప్రభావితం చేసే విశిష్ట కంపన శక్తి ఉంటుంది.",
    "Calculate Your Numbers": "మీ సంఖ్యలను లెక్కించండి",
    "Date of Birth (DD/MM/YYYY)": "పుట్టిన తేదీ (తేదీ/నెల/సంవత్సరం)",
    "Calculate My Numbers": "నా సంఖ్యలను లెక్కించు",
    "Core Numbers": "ముఖ్య సంఖ్యలు",
