    "Derived from your birth date, this is the most important number — it reveals your life's purpose and the path you are meant to walk.": "పుట్టిన తేదీ ఆధారంగా లెక్కింపబడే ప్రధాన సంఖ్య — ఇది మీ జీవిత లక్ష్యాన్ని మరియు నడవాల్సిన దివ్య మార్గాన్ని సూచిస్తుంది.",
    "Destiny Number": "డెస్టినీ సంఖ్య (భాగ్య సంఖ్య)",
    "Calculated from your full birth name, this reveals your talents, abilities, and the goals you are destined to achieve.": "మీ పేరు ఆధారంగా లెక్కింపబడే సంఖ్య — ఇది మీ నైపుణ్యాలు మరియు మీరు సాధించబోయే విజయాలను తెలియజేస్తుంది.",
    "Soul Urge Number": "సోల్ అర్జ్ సంఖ్య (ఆత్మ సంఖ్య)",
    "Derived from the vowels in your name, this reveals your innermost desires, motivations, and what truly makes your soul happy.": "మీ పేరులోని అచ్చుల ఆధారంగా మీ అంతరంగ ఆశలు, అంతర్గత ప్రేరణలను తెలియజేసే సంఖ్య.",
    "Life Path": "జీవిత మార్గం",
    "Destiny": "భాగ్యం",
    "Muhurat": "శుభ ముహూర్తం",
    "Auspicious timings for life events": "జీవిత శుభ కార్యాల కోసం పవిత్ర ముహూర్తాలు",
    "Muhurat is the Vedic science of selecting the most auspicious time for important life events. Starting any significant activity at the right cosmic moment ensures divine blessings and minimises obstacles.": "ముహూర్తం అనేది ముఖ్యమైన పనుల కోసం శుభ సమయాన్ని ఎంచుకునే వేద విజ్ఞానం. అనుకూలమైన గ్రహ కాలంలో ప్రారంభించిన కార్యాలకు దైవాశీస్సులు లభించి ఆటంకాలు తొలగుతాయి.",
