    "Spiritual Guidance": "ఆధ్యాత్మిక మార్గదర్శనం",
    "Illuminate your soul's sacred path": "మీ ఆత్మ సాధనా మార్గాన్ని ప్రకాశవంతం చేసుకోండి",
    "Beyond the material world lies the realm of the soul. Our spiritual astrologers and guides help you understand your karmic journey, past life influences, dharmic purpose, and the spiritual practices best suited for your soul's evolution.": "భౌతిక ప్రపంచాన్ని మించి ఆత్మ ప్రయాణం ఉంటుంది. మా ఆధ్యాత్మిక జ్యోతిష్యులు మీ పూర్వజన్మ కర్మలు, ధార్మిక కర్తవ్యం మరియు సాధనలకు సరైన మార్గాన్ని నిర్దేశిస్తారు.",
