    "Explore karmic debts and past life influences through the 12th house, Saturn, and Rahu-Ketu axis in your birth chart.": "12వ భావం, శని మరియు రాహు-కేతువుల ద్వారా పూర్వజన్మ కర్మ బంధాలను తెలుసుకోండి.",
    "Dharma & Life Purpose": "ధర్మం & జీవిత పరమార్థం",
    "Discover your soul's true purpose through the Atmakaraka planet and the 9th house of dharma and higher wisdom.": "ఆత్మకారక గ్రహం మరియు 9వ ధర్మ స్థానం ద్వారా జీవిత అసలైన ధ్యేయాన్ని గ్రహించండి.",
    "Spiritual Practice Guidance": "ఆధ్యాత్మిక సాధన మార్గదర్శనం",
    "Receive personalised recommendations for meditation, yoga, mantra, and spiritual practices aligned with your birth chart.": "మీ జాతకానికి అనువైన ధ్యానం, యోగా, మంత్ర జపం మరియు దైవారాధన సలహాలు పొందండి.",
    "Ishta Devata (Personal Deity)": "ఇష్ట దైవం",
    "Identify your personal deity through the Atmakaraka and Karakamsha chart for deepened spiritual connection.": "ఆత్మకారక మరియు కారకాంశ కుండలి ద్వారా మీ ఇష్ట దైవాన్ని తెలుసుకుని ఉపాసించండి.",
