    "Decode the numbers of your destiny": "अपनी जन्मतिथि के अंकों से भाग्य का रहस्य जानें",
    "Numerology is the ancient science of numbers and their divine influence on human life. Every number carries a unique vibration that shapes your personality, destiny, and life path.": "अंकशास्त्र संख्याओं का वह प्राचीन विज्ञान है जो जीवन पर ग्रहों के प्रभाव को स्पष्ट करता है। प्रत्येक अंक का विशेष स्पंदन आपके भाग्य और व्यक्तित्व को आकार देता है।",
