    "Derived from your birth date, this is the most important number — it reveals your life's purpose and the path you are meant to walk.": "जन्मतिथि से प्राप्त सबसे महत्वपूर्ण अंक — जो आपके जीवन के उद्देश्य और चलने योग्य मार्ग को प्रकट करता है।",
    "Destiny Number": "नामांक (Destiny Number)",
    "Calculated from your full birth name, this reveals your talents, abilities, and the goals you are destined to achieve.": "आपके पूर्ण नाम से प्राप्त अंक — जो आपकी आंतरिक क्षमताओं और प्राप्त होने वाली उपलब्धियों को दर्शाता है।",
    "Soul Urge Number": "आत्म बोध अंक (Soul Urge)",
    "Derived from the vowels in your name, this reveals your innermost desires, motivations, and what truly makes your soul happy.": "नाम के स्वरों से प्राप्त अंक — जो आपकी आंतरिक इच्छाओं और आत्मा को प्रसन्न रखने वाली बातों को उजागर करता है।",
