    "Destiny": "भाग्य",
    "Muhurat": "शुभ मुहूर्त",
    "Auspicious timings for life events": "शुभ कार्यों के लिए सर्वोत्तम वैदिक मुहूर्त",
    "Muhurat is the Vedic science of selecting the most auspicious time for important life events. Starting any significant activity at the right cosmic moment ensures divine blessings and minimises obstacles.": "मुहूर्त शुभ समय के चयन का वैदिक विज्ञान है। सही खगोलीय घड़ी में शुरू किए गए कार्यों पर देवी-देवताओं का आशीर्वाद बना रहता है और बाधाएं दूर होती हैं।",
    "Upcoming Auspicious Dates": "आगामी शुभ मुहूर्त तिथियां",
