    "Illuminate your soul's sacred path": "अपनी आत्मा का दिव्य मार्ग आलोकित करें",
    "Beyond the material world lies the realm of the soul. Our spiritual astrologers and guides help you understand your karmic journey, past life influences, dharmic purpose, and the spiritual practices best suited for your soul's evolution.": "भौतिक संसार से परे आत्मा का मार्ग है। हमारे आध्यात्मिक ज्योतिषी आपके पूर्वजन्म के कर्म, धार्मिक उद्देश्य और साधना का सच्चा मार्ग प्रशस्त करते हैं।",
    "Spiritual Services": "आध्यात्मिक सेवाएं",
    "Karma & Past Life Analysis": "कर्म एवं पूर्वजन्म विश्लेषण",
    "Explore karmic debts and past life influences through the 12th house, Saturn, and Rahu-Ketu axis in your birth chart.": "द्वादश भाव, शनि और राहु-केतु के माध्यम से पूर्व जन्मों के ऋण और कर्म बंधनों को समझें।",
    "Dharma & Life Purpose": "धर्म एवं जीवन का ध्येय",
    "Discover your soul's true purpose through the Atmakaraka planet and the 9th house of dharma and higher wisdom.": "आत्मकारक ग्रह और नवम भाव से आत्मा के वास्तविक लक्ष्य और कर्तव्य को जानें।",
    "Spiritual Practice Guidance": "साधना एवं ध्यान मार्गदर्शन",
    "Receive personalised recommendations for meditation, yoga, mantra, and spiritual practices aligned with your birth chart.": "अपनी कुंडली के अनुकूल ध्यान, योग, मंत्र जप और दैनिक साधना के सुझाव प्राप्त करें।",
    "Ishta Devata (Personal Deity)": "इष्ट देवता",
    "Identify your personal deity through the Atmakaraka and Karakamsha chart for deepened spiritual connection.": "आत्मकारक एवं कारकांश चक्र से अपने इष्ट देवता की पहचान कर उनकी उपासना करें।",
