    "Our expert astrologers prepare detailed, personalised PDF reports that provide deep insights into every aspect of your life. Each report is hand-crafted based on your exact birth details.": "आपकी सटीक जन्म कुंडली के आधार पर तैयार की गई गहन, व्यक्तिगत PDF रिपोर्ट जो जीवन के हर पहलू को स्पष्ट करती है।",
