    "Your birth chart holds the blueprint of your professional life. Vedic astrology reveals the most favourable career paths, promotion timings, and business opportunities aligned with your planetary positions.": "உங்கள் பிறப்பு ஜாதகம் உங்கள் தொழில் வாழ்க்கையின் வரைபடமாகும். கிரக நிலைகளின்படி மிகவும் சாதகமான தொழில், பதவி உயர்வு நேரம் மற்றும் வணிக வாய்ப்புகளை வேத ஜோதிடம் வெளிப்படுத்துகிறது.",
