    "Promotion & Growth Timing": "பதவி உயர்வு & வளர்ச்சி நேரம்",
    "Pinpoint the exact Dasha and transit periods when career advancement is most likely to occur.": "தொழில் முன்னேற்றம் ஏற்படும் துல்லியமான தசா புக்தி மற்றும் கோச்சார காலங்களைக் கண்டறியுங்கள்.",
    "Job vs Business": "வேலை அல்லது வியாபாரம்",
    "Determine whether employment or entrepreneurship is written in your stars for maximum success.": "அதிகபட்ச வெற்றிக்கு வேலை அல்லது சொந்த தொழில் எது சிறந்தது என்பதைத் தீர்மானியுங்கள்.",
