    "Find your destined life partner": "உங்கள் வாழ்க்கை துணையை அறியுங்கள்",
    "Marriage is one of the most significant events in life. Vedic astrology provides deep insights into marriage timing, partner characteristics, compatibility, and the strength of your marital bond through the 7th house and Venus analysis.": "திருமணம் வாழ்க்கையின் முக்கியமான தருணம். 7-ஆம் வீடு மற்றும் சுக்கிரனின் பகுப்பாய்வு மூலம் திருமண காலம், துணையின் குணம், பொருத்தம் ஆகியவற்றை வேத ஜோதிடம் துல்லியமாக விளக்குகிறது.",
