    "Every successful business has cosmic timing. Vedic astrology helps entrepreneurs identify the best time to launch, expand, or pivot their business, choose the right partners, and navigate challenging periods with confidence.": "ಪ್ರತಿ ಯಶಸ್ವಿ ವ್ಯಾಪಾರಕ್ಕೂ ಶುಭ ಮುಹೂರ್ತ ಅಗತ್ಯ. ಉದ್ಯಮ ಪ್ರಾರಂಭ, ವಿಸ್ತರಣೆ ಮತ್ತು ಪಾಲುದಾರರ ಹೊಂದಾಣಿಕೆಗೆ ವೈದಿಕ ಜ್ಯೋತಿಷ್ಯ ಮಾರ್ಗದರ್ಶನ ನೀಡುತ್ತದೆ.",
    "Business Insights": "ವ್ಯಾಪಾರ ಒಳನೋಟಗಳು",
    "Business Launch Timing": "ವ್ಯಾಪಾರ ಪ್ರಾರಂಭದ ಮುಹೂರ್ತ",
    "Identify the most auspicious Muhurat for launching your business, signing contracts, or opening new ventures.": "ಹೊಸ ವ್ಯಾಪಾರ ಪ್ರಾರಂಭ, ಒಪ್ಪಂದಗಳು ಮತ್ತು ನೂತನ ಯೋಜನೆಗಳಿಗೆ ಅತ್ಯಂತ ಶುಭ ಮುಹೂರ್ತ ತಿಳಿಯಿರಿ.",
    "Partnership Compatibility": "ಪಾಲುದಾರಿಕೆ ಹೊಂದಾಣಿಕೆ",
    "Analyse the compatibility between business partners using Synastry and composite chart techniques.": "ಪಾಲುದಾರರ ನಡುವಿನ ಗ್ರಹ ಹೊಂದಾಣಿಕೆ ಮತ್ತು ವ್ಯಾಪಾರ ಯಶಸ್ಸನ್ನು ವಿಶ್ಲೇಷಿಸಿ.",
    "Growth & Expansion Periods": "ಬೆಳವಣಿಗೆ ಮತ್ತು ವಿಸ್ತರಣೆಯ ಸಮಯ",
    "Identify Jupiter and Venus transits that signal the best windows for business expansion and investment.": "ವ್ಯಾಪಾರ ವಿಸ್ತರಣೆ ಮತ್ತು ಹೂಡಿಕೆಗೆ ಅತ್ಯುತ್ತಮವಾದ ಗುರು ಹಾಗೂ ಶುಕ್ರ ಗ್ರಹಗಳ ಸಂಚಾರವನ್ನು ತಿಳಿಯಿರಿ.",
    "Risk & Challenge Periods": "ಸವಾಲುಗಳು ಮತ್ತು ಅಡೆತಡೆಗಳ ಸಮಯ",
    "Foresee Saturn and Rahu transits that may bring obstacles, and prepare strategic remedies in advance.": "ಶನಿ ಮತ್ತು ರಾಹು ಸಂಚಾರದಿಂದ ಉಂಟಾಗಬಹುದಾದ ಅಡೆತಡೆಗಳನ್ನು ಮುಂಚಿತವಾಗಿಯೇ ಅರಿತು ಪರಿಹಾರ ಮಾಡಿಕೊಳ್ಳಿ.",
    "Business Sectors by Planet": "ಗ್ರಹಗಳ ಪ್ರಕಾರ ವ್ಯಾಪಾರ ಕ್ಷೇತ್ರಗಳು",
    "Finance Astrology": "ಹಣಕಾಸು ಜ್ಯೋತಿಷ್ಯ",
    "Wealth, investments & financial destiny": "ಸಂಪತ್ತು, ಹೂಡಿಕೆಗಳು ಮತ್ತು ಧನ ಯೋಗ",
    "The 2nd, 5th, 8th, and 11th houses in your birth chart govern wealth accumulation, speculative gains, inheritance, and income respectively. Our expert astrologers decode your financial destiny and guide you toward prosperity.": "ಕುಂಡಲಿಯ 2, 5, 8 ಮತ್ತು 11ನೇ ಸ್ಥಾನಗಳು ಅನುಕ್ರಮವಾಗಿ ಧನ ಸಂಗ್ರಹ, ಲಾಭ, ಪಿತ್ರಾರ್ಜಿತ ಆಸ್ತಿ ಮತ್ತು ಆದಾಯವನ್ನು ನಿರ್ಧರಿಸುತ್ತವೆ. ನಮ್ಮ ತಜ್ಞರು ನಿಮ್ಮ ಆರ್ಥಿಕ ಭವಿಷ್ಯವನ್ನು ವಿಶ್ಲೇಷಿಸುತ್ತಾರೆ.",
    "Financial Analysis": "ಹಣಕಾಸು ವಿಶ್ಲೇಷಣೆ",
    "Wealth Accumulation Periods": "ಧನ ಪ್ರಾಪ್ತಿ ಕಾಲ",
    "Identify Jupiter and Venus Dasha periods that bring maximum financial growth and wealth accumulation.": "ಗರಿಷ್ಠ ಆರ್ಥಿಕ ಬೆಳವಣಿಗೆ ಮತ್ತು ಸಂಪತ್ತು ಗಳಿಸಲು ಅನುಕೂಲಕರವಾದ ಗುರು, ಶುಕ್ರ ದಶಾ ಕಾಲಗಳನ್ನು ತಿಳಿಯಿರಿ.",
    "Investment Timing": "ಹೂಡಿಕೆಯ ಶುಭ ಸಮಯ",
    "Determine the best planetary windows for stock market investments, real estate purchases, and gold buying.": "ಷೇರು ಮಾರುಕಟ್ಟೆ, ರಿಯಲ್ ಎಸ್ಟೇಟ್ ಮತ್ತು ಚಿನ್ನದ ಖರೀದಿಗೆ ಅತ್ಯಂತ ಸೂಕ್ತ ಗ್ರಹ ಸ್ಥಿತಿಗಳನ್ನು ತಿಳಿಯಿರಿ.",
    "Financial Loss Prevention": "ಹಣಕಾಸು ನಷ್ಟ ತಡೆಗಟ್ಟುವಿಕೆ",
    "Foresee Ketu and Saturn transits that may cause financial setbacks and take preventive measures.": "ಧನ ನಷ್ಟಕ್ಕೆ ಕಾರಣವಾಗುವ ಗ್ರಹ ಸಂಚಾರಗಳನ್ನು ಮುಂಚಿತವಾಗಿ ಗ್ರಹಿಸಿ ಸೂಕ್ತ ರಕ್ಷಣಾ ಕ್ರಮ ಕೈಗೊಳ್ಳಿ.",
    "Property & Real Estate": "ಆಸ್ತಿ ಮತ್ತು ಭೂಮಿ",
    "Analyse the 4th house for property ownership timing and the best periods for buying or selling property.": "4ನೇ ಮನೆಯ ಆಧಾರದ ಮೇಲೆ ಮನೆ, ಭೂಮಿ ಖರೀದಿ ಅಥವಾ ಮಾರಾಟಕ್ಕೆ ಅತ್ಯುತ್ತಮ ಸಮಯವನ್ನು ತಿಳಿಯಿರಿ.",
    "Wealth Houses": "ಧನ ಸ್ಥಾನಗಳು",
    "2nd House": "2ನೇ ಮನೆ",
