    "8th House": "8ನೇ ಮನೆ",
    "Inheritance": "ಪಿತ್ರಾರ್ಜಿತ ಸಂಪತ್ತು",
    "11th House": "11ನೇ ಮನೆ",
    "Income & Profits": "ಆದಾಯ ಮತ್ತು ಲಾಭ ಸ್ಥಾನ",
    "Tarot Reading": "ಟ್ಯಾರೋ ಓದುವಿಕೆ",
    "Ancient wisdom through sacred cards": "ಪವಿತ್ರ ಕಾರ್ಡ್‌ಗಳ ಮೂಲಕ ಪ್ರಾಚೀನ ದೈವಿಕ ಮಾರ್ಗದರ್ಶನ",
    "Tarot is a powerful divination tool that uses 78 symbolic cards to reveal hidden truths, illuminate life paths, and provide guidance on love, career, and spiritual growth. Each card carries profound archetypal wisdom.": "ಟ್ಯಾರೋ ಎಂಬುದು 78 ಸಂಕೇತಗಳ ಕಾರ್ಡ್‌ಗಳಿಂದ ಕೂಡಿದ ದೈವಿಕ ಭವಿಷ್ಯ ದರ್ಶನ. ಇದು ಪ್ರೀತಿ, ವೃತ್ತಿ ಮತ್ತು ಆಧ್ಯಾತ್ಮಿಕ ಬೆಳವಣಿಗೆಗೆ ನಿಖರ ಮಾರ್ಗದರ್ಶನ ನೀಡುತ್ತದೆ.",
    "Daily Card Draw": "ದೈನಂದಿನ ಟ್ಯಾರೋ ಕಾರ್ಡ್",
    "Your Card of the Day": "ಇಂದಿನ ನಿಮ್ಮ ವಿಶೇಷ ಕಾರ್ಡ್",
    "The Star": "ದಿ ಸ್ಟಾರ್ (The Star)",
    "Hope, faith, purpose, renewal, and spirituality. A period of calm after a storm — trust in the universe's plan.": "ಭರವಸೆ, ನಂಬಿಕೆ, ನವಚೈತನ್ಯ ಮತ್ತು ಆಧ್ಯಾತ್ಮಿಕ ಶಾಂತಿ. ಚಂಡಮಾರುತ ಮುಗಿದ ನಂತರ ಮೂಡುವ ಪ್ರಶಾಂತತೆ — ಬ್ರಹ್ಮಾಂಡದ ಸಂಕಲ್ಪವನ್ನು ನಂಬಿ.",
    "Reading Types": "ರೀಡಿಂಗ್ ವಿಧಗಳು",
    "Love & Relationship Spread": "ಪ್ರೀತಿ ಮತ್ತು ಸಂಬಂಧಗಳ ಸ್ಪ್ರೆಡ್",
    "A 5-card spread revealing the current state of your love life, obstacles, and the path forward.": "ಪ್ರೀತಿಯ ಜೀವನದ ಸ್ಥಿತಿ, ಎದುರಾಗುವ ಅಡೆತಡೆಗಳು ಮತ್ತು ಮುಂದಿನ ಹಾದಿಯನ್ನು ತಿಳಿಸುವ 5 ಕಾರ್ಡ್‌ಗಳ ಭವಿಷ್ಯ.",
    "Career & Finance Spread": "ವೃತ್ತಿ ಮತ್ತು ಹಣಕಾಸು ಸ್ಪ್ರೆಡ್",
    "A 3-card spread covering your current career situation, challenges, and the best action to take.": "ಪ್ರಸ್ತುತ ಉದ್ಯೋಗ ಪರಿಸ್ಥಿತಿ ಮತ್ತು ತೆಗೆದುಕೊಳ್ಳಬೇಕಾದ ನಿರ್ಧಾರಗಳನ್ನು ತಿಳಿಸುವ 3 ಕಾರ್ಡ್‌ಗಳ ಸ್ಪ್ರೆಡ್.",
    "Celtic Cross Spread": "ಸೆಲ್ಟಿಕ್ ಕ್ರಾಸ್ ಸಮಗ್ರ ಸ್ಪ್ರೆಡ್",
    "The most comprehensive 10-card spread providing a complete overview of your life situation.": "ಜೀವನದ ಪ್ರಮುಖ ಹಂತಗಳನ್ನು ಸಮಗ್ರವಾಗಿ ವಿವರಿಸುವ 10 ಕಾರ್ಡ್‌ಗಳ ಸೆಲ್ಟಿಕ್ ಕ್ರಾಸ್ ಸ್ಪ್ರೆಡ್.",
    "Major Arcana Cards": "ಮೇಜರ್ ಅರ್ಕಾನಾ ಕಾರ್ಡ್‌ಗಳು",
    "The Fool": "ದಿ ಫೂಲ್ (The Fool)",
    "The Magician": "ದಿ ಮ್ಯಾಜಿಶಿಯನ್ (The Magician)",
    "The High Priestess": "ದಿ ಹೈ ಪ್ರೀಸ್ಟೆಸ್ (The High Priestess)",
    "The Empress": "ದಿ ಎಂಪ್ರೆಸ್ (The Empress)",
    "The Emperor": "ದಿ ಎಂಪರರ್ (The Emperor)",
    "The Hierophant": "ದಿ ಹೈರೋಫ್ಯಾಂಟ್ (The Hierophant)",
    "The Lovers": "ದಿ ಲವರ್ಸ್ (The Lovers)",
    "The Chariot": "ದಿ ಚಾರಿಯಟ್ (The Chariot)",
    "Decode the numbers of your destiny": "ನಿಮ್ಮ ಜನ್ಮ ದಿನಾಂಕದ ರಹಸ್ಯ ಸಂಖ್ಯೆಗಳನ್ನು ತಿಳಿಯಿರಿ",
    "Numerology is the ancient science of numbers and their divine influence on human life. Every number carries a unique vibration that shapes your personality, destiny, and life path.": "ಸಂಖ್ಯಾಶಾಸ್ತ್ರವು ಮಾನವ ಜೀವನದ ಮೇಲೆ ಸಂಖ್ಯೆಗಳ ದೈವಿಕ ಪ್ರಭಾವವನ್ನು ವಿವರಿಸುವ ಪ್ರಾಚೀನ ವಿಜ್ಞಾನ. ಪ್ರತಿಯೊಂದು ಸಂಖ್ಯೆಯೂ ನಿಮ್ಮ ವ್ಯಕ್ತಿತ್ವ ಮತ್ತು ಭವಿಷ್ಯವನ್ನು ನಿರ್ಧರಿಸುವ ಶಕ್ತಿ ಹೊಂದಿದೆ.",
    "Calculate Your Numbers": "ನಿಮ್ಮ ಸಂಖ್ಯೆಗಳನ್ನು ಲೆಕ್ಕಹಾಕಿ",
    "Date of Birth (DD/MM/YYYY)": "ಜನ್ಮ ದಿನಾಂಕ (ದಿನ/ತಿಂಗಳು/ವರ್ಷ)",
    "Calculate My Numbers": "ನನ್ನ ಸಂಖ್ಯೆಗಳನ್ನು ಲೆಕ್ಕಹಾಕಿ",
    "Core Numbers": "ಮುಖ್ಯ ಸಂಖ್ಯೆಗಳು",
    "Life Path Number": "ಲೈಫ್ ಪಾತ್ ಸಂಖ್ಯೆ (ಜೀವನ ಪಥ)",
    "Derived from your birth date, this is the most important number — it reveals your life's purpose and the path you are meant to walk.": "ಜನ್ಮ ದಿನಾಂಕದಿಂದ ಪಡೆಯಲಾಗುವ ಪ್ರಮುಖ ಸಂಖ್ಯೆ — ಇದು ನಿಮ್ಮ ಜೀವನದ ಗುರಿ ಮತ್ತು ನೀವು ಸಾಗಬೇಕಾದ ಮಾರ್ಗವನ್ನು ತೋರಿಸುತ್ತದೆ.",
    "Destiny Number": "ಡೆಸ್ಟಿನಿ ಸಂಖ್ಯೆ (ಭಾಗ್ಯ ಸಂಖ್ಯೆ)",
    "Calculated from your full birth name, this reveals your talents, abilities, and the goals you are destined to achieve.": "ನಿಮ್ಮ ಪೂರ್ಣ ಹೆಸರಿನಿಂದ ಪಡೆಯಲಾಗುವ ಸಂಖ್ಯೆ — ಇದು ನಿಮ್ಮ ಸಾಮರ್ಥ್ಯ ಮತ್ತು ನೀವು ಸಾಧಿಸಲಿರುವ ಯಶಸ್ಸನ್ನು ತಿಳಿಸುತ್ತದೆ.",
    "Soul Urge Number": "ಸೋಲ್ ಅರ್ಜ್ ಸಂಖ್ಯೆ (ಆತ್ಮ ಸಂಖ್ಯೆ)",
    "Derived from the vowels in your name, this reveals your innermost desires, motivations, and what truly makes your soul happy.": "ನಿಮ್ಮ ಹೆಸರಿನ ಸ್ವರಾಕ್ಷರಗಳಿಂದ ನಿಮ್ಮ ಆಂತರಿಕ ಆಸೆಗಳು ಮತ್ತು ಆಕಾಂಕ್ಷೆಗಳನ್ನು ತಿಳಿಸುವ ಸಂಖ್ಯೆ.",
    "Life Path": "ಜೀವನ ಪಥ",
    "Destiny": "ಭಾಗ್ಯ",
    "Muhurat": "ಶುಭ ಮುಹೂರ್ತ",
    "Auspicious timings for life events": "ಶುಭ ಕಾರ್ಯಗಳಿಗಾಗಿ ಮಂಗಳಕರ ಸಮಯ",
    "Muhurat is the Vedic science of selecting the most auspicious time for important life events. Starting any significant activity at the right cosmic moment ensures divine blessings and minimises obstacles.": "ಮುಹೂರ್ತವು ಪ್ರಮುಖ ಕಾರ್ಯಗಳಿಗೆ ಮಂಗಳಕರ ಸಮಯವನ್ನು ಆರಿಸುವ ವೈದಿಕ ವಿಜ್ಞಾನವಾಗಿದೆ. ಶುಭ ಘಳಿಗೆಯಲ್ಲಿ ಆರಂಭಿಸಿದ ಕಾರ್ಯಗಳಿಗೆ ದೈವಾನುಗ್ರಹ ದೊರೆತು ಅಡೆತಡೆಗಳು ನಿವಾರಣೆಯಾಗುತ್ತವೆ.",
    "Upcoming Auspicious Dates": "ಮುಂಬರುವ ಶುಭ ಮುಹೂರ್ತ ದಿನಾಂಕಗಳು",
