    "Spiritual Guidance": "ಆಧ್ಯಾತ್ಮಿಕ ಮಾರ್ಗದರ್ಶನ",
    "Illuminate your soul's sacred path": "ನಿಮ್ಮ ಆತ್ಮದ ದೈವಿಕ ಮಾರ್ಗವನ್ನು ಬೆಳಗಿಸಿ",
    "Beyond the material world lies the realm of the soul. Our spiritual astrologers and guides help you understand your karmic journey, past life influences, dharmic purpose, and the spiritual practices best suited for your soul's evolution.": "ಭೌತಿಕ ಜಗತ್ತನ್ನು ಮೀರಿದ್ದು ಆತ್ಮದ ಪಯಣ. ನಮ್ಮ ಆಧ್ಯಾತ್ಮಿಕ ಜ್ಯೋತಿಷಿಗಳು ನಿಮ್ಮ ಪೂರ್ವಜನ್ಮದ ಕರ್ಮಗಳು, ಧಾರ್ಮಿಕ ಕರ್ತವ್ಯ ಮತ್ತು ಸಾಧನೆಗೆ ಸೂಕ್ತ ಮಾರ್ಗದರ್ಶನ ನೀಡುತ್ತಾರೆ.",
    "Spiritual Services": "ಆಧ್ಯಾತ್ಮಿಕ ಸೇವೆಗಳು",
    "Karma & Past Life Analysis": "ಕರ್ಮ ಮತ್ತು ಪೂರ್ವಜನ್ಮ ವಿಶ್ಲೇಷಣೆ",
    "Explore karmic debts and past life influences through the 12th house, Saturn, and Rahu-Ketu axis in your birth chart.": "12ನೇ ಮನೆ, ಶನಿ ಮತ್ತು ರಾಹು-ಕೇತುಗಳ ಮೂಲಕ ಪೂರ್ವಜನ್ಮದ ಕರ್ಮ ಋಣಗಳನ್ನು ತಿಳಿಯಿರಿ.",
    "Dharma & Life Purpose": "ಧರ್ಮ ಮತ್ತು ಜೀವನದ ಉದ್ದೇಶ",
    "Discover your soul's true purpose through the Atmakaraka planet and the 9th house of dharma and higher wisdom.": "ಆತ್ಮಕಾರಕ ಗ್ರಹ ಮತ್ತು 9ನೇ ಧರ್ಮ ಸ್ಥಾನದ ಮೂಲಕ ಜೀವನದ ನೈಜ ಗುರಿಯನ್ನು ಅರಿಯಿರಿ.",
