    "Understand the nature, appearance, and qualities of your future spouse through 7th house lord and Venus placement.": "ഏഴാം ഭാവാധിപനിലൂടെയും ശുക്രനിലൂടെയും ഭാവി പങ്കാളിയുടെ രൂപം, സ്വഭാവം, ഗുണങ്ങൾ എന്നിവ അറിയുക.",
    "Kundli Milan (36 Gunas)": "ജാതക പൊരുത്തം (36 ഗുണങ്ങൾ)",
    "Complete compatibility matching using traditional Ashtakoot system covering all 8 aspects of marital harmony.": "ദാമ്പത്യ ഭദ്രതയ്ക്കായി പരമ്പരാഗത അഷ്ടകൂട രീതിയിലുള്ള സമഗ്ര 36 ഗുണ പൊരുത്തം.",
    "Mangal Dosha Analysis": "ചൊവ്വാ ദോഷ വിശകലനം",
    "Identify and assess Mangal Dosha, its severity, and effective remedies to ensure a harmonious marriage.": "ചൊവ്വാ ദോഷത്തിന്റെ തീവ്രത തിരിച്ചറിഞ്ഞ് സമാധാനപരമായ വിവാഹ ജീവിതത്തിനായുള്ള വൈദിക പരിഹാരങ്ങൾ.",
    "Compatibility Score": "പൊരുത്ത സ്കോർ",
    "Business Astrology": "ബിസിനസ്സ് ജ്യോതിഷം",
    "Align your enterprise with the cosmos": "നിങ്ങളുടെ ബിസിനസ്സ് വിജയത്തെ ഗ്രഹ സ്വാധീനവുമായി ബന്ധിപ്പിക്കുക",
    "Every successful business has cosmic timing. Vedic astrology helps entrepreneurs identify the best time to launch, expand, or pivot their business, choose the right partners, and navigate challenging periods with confidence.": "എല്ലാ വിജയകരമായ ബിസിനസ്സിനും ഒരു ശുഭ മുഹൂർത്തമുണ്ട്. സംരംഭം തുടങ്ങാനും പങ്കാളികളെ തിരഞ്ഞെടുക്കാനും വെല്ലുവിളികൾ തരണം ചെയ്യാനും വൈദിക ജ്യോതിഷം സഹായിക്കുന്നു.",
    "Business Insights": "ബിസിനസ്സ് ഉൾക്കാഴ്ചകൾ",
    "Business Launch Timing": "ബിസിനസ്സ് ആരംഭ മുഹൂർത്തം",
    "Identify the most auspicious Muhurat for launching your business, signing contracts, or opening new ventures.": "പുതിയ സംരംഭങ്ങൾ തുടങ്ങാനും കരാറുകൾ ഒപ്പിടാനും ഏറ്റവും ഉചിതമായ ശുഭ മുഹൂർത്തം അറിയുക.",
    "Partnership Compatibility": "പങ്കാളിത്ത പൊരുത്തം",
    "Analyse the compatibility between business partners using Synastry and composite chart techniques.": "ബിസിനസ്സ് പങ്കാളികൾ തമ്മിലുള്ള ഗ്രഹ പൊരുത്തവും ലാഭ സാധ്യതകളും വിശകലനം ചെയ്യുക.",
    "Growth & Expansion Periods": "വളർച്ചയും വിപുലീകരണ സമയവും",
    "Identify Jupiter and Venus transits that signal the best windows for business expansion and investment.": "നിക്ഷേപങ്ങൾക്കും ബിസിനസ്സ് വിപുലീകരണത്തിനും അനുകൂലമായ വ്യാഴ, ശുക്ര സഞ്ചാരങ്ങൾ അറിയുക.",
    "Risk & Challenge Periods": "തടസ്സങ്ങളും വെല്ലുവിളികളും നിറഞ്ഞ കാലം",
    "Foresee Saturn and Rahu transits that may bring obstacles, and prepare strategic remedies in advance.": "ശനി, രാഹു ഗ്രഹങ്ങൾ കൊണ്ടുവരുന്ന പ്രതിസന്ധികൾ മുൻകൂട്ടി കണ്ട് പരിഹാരങ്ങൾ ചെയ്യുക.",
    "Business Sectors by Planet": "ഗ്രഹങ്ങൾ നിർദ്ദേശിക്കുന്ന ബിസിനസ്സ് മേഖലകൾ",
    "Finance Astrology": "സാമ്പത്തിക ജ്യോതിഷം",
    "Wealth, investments & financial destiny": "സമ്പത്ത്, നിക്ഷേപം & ധന യോഗം",
    "The 2nd, 5th, 8th, and 11th houses in your birth chart govern wealth accumulation, speculative gains, inheritance, and income respectively. Our expert astrologers decode your financial destiny and guide you toward prosperity.": "ജാതകത്തിലെ 2, 5, 8, 11 ഭാവങ്ങൾ യഥാക്രമം സമ്പാദ്യം, ഭാഗ്യം, പാരമ്പര്യ സ്വത്ത്, വരുമാനം എന്നിവയെ നിയന്ത്രിക്കുന്നു. ഞങ്ങളുടെ ജ്യോത്സ്യന്മാർ നിങ്ങളുടെ ധനസ്ഥിതി വ്യക്തമാക്കുന്നു.",
    "Financial Analysis": "സാമ്പത്തിക വിശകലനം",
    "Wealth Accumulation Periods": "ധന സമാഹരണ കാലം",
    "Identify Jupiter and Venus Dasha periods that bring maximum financial growth and wealth accumulation.": "പരമാവധി സാമ്പത്തിക വളർച്ചയും സമ്പാദ്യവും നൽകുന്ന വ്യാഴ, ശുക്ര ദശാ കാലങ്ങൾ കണ്ടെത്തുക.",
    "Investment Timing": "നിക്ഷേപത്തിനുള്ള ശുഭ സമയം",
    "Determine the best planetary windows for stock market investments, real estate purchases, and gold buying.": "ഓഹരി വിപണി, ഭൂമി വാങ്ങൽ, സ്വർണ്ണം വാങ്ങൽ എന്നിവയ്ക്കുള്ള ഏറ്റവും മികച്ച സമയം അറിയുക.",
    "Financial Loss Prevention": "സാമ്പത്തിക നഷ്ടം തടയൽ",
    "Foresee Ketu and Saturn transits that may cause financial setbacks and take preventive measures.": "ധന നഷ്ടത്തിന് കാരണമായേക്കാവുന്ന ഗ്രഹ സഞ്ചാരങ്ങൾ മുൻകൂട്ടി കണ്ട് ജാഗ്രത പുലർത്തുക.",
    "Property & Real Estate": "ഭൂമിയും കെട്ടിടവും",
    "Analyse the 4th house for property ownership timing and the best periods for buying or selling property.": "നാലാം ഭാവം വിശകലനം ചെയ്ത് വസ്തു വകകൾ വാങ്ങുന്നതിനും വിൽക്കുന്നതിനുമുള്ള സമയം കണ്ടെത്തുക.",
