    "Speculation & Gains": "ഭാഗ്യ ലാഭങ്ങൾ",
    "8th House": "എട്ടാം ഭാവം",
    "Inheritance": "പാരമ്പര്യ സ്വത്ത്",
    "11th House": "പതിനൊന്നാം ഭാവം",
    "Income & Profits": "വരുമാനവും ലാഭവും",
    "Tarot Reading": "ടാരറ്റ് വായന",
    "Ancient wisdom through sacred cards": "വിശുദ്ധ കാർഡുകളിലൂടെയുള്ള പുരാതന ദിവ്യജ്ഞാനം",
    "Tarot is a powerful divination tool that uses 78 symbolic cards to reveal hidden truths, illuminate life paths, and provide guidance on love, career, and spiritual growth. Each card carries profound archetypal wisdom.": "78 കാർഡുകളിലൂടെ രഹസ്യ സത്യങ്ങൾ വെളിപ്പെടുത്തുന്ന ആത്മീയ ഭവിഷ്യൽ ദർശനമാണ് ടാരറ്റ്. ഇത് പ്രണയം, കരിയർ, ആത്മീയത എന്നിവയിൽ വ്യക്തമായ മാർഗ്ഗനിർദ്ദേശം നൽകുന്നു.",
    "Daily Card Draw": "ഇന്നത്തെ ടാരറ്റ് കാർഡ്",
    "Your Card of the Day": "നിങ്ങളുടെ ഇന്നത്തെ പ്രത്യേക കാർഡ്",
    "The Star": "ദി സ്റ്റാർ (The Star)",
    "Hope, faith, purpose, renewal, and spirituality. A period of calm after a storm — trust in the universe's plan.": "പ്രതീക്ഷ, വിശ്വാസം, നവോന്മേഷം, ആത്മീയ ശാന്തി. പ്രതിസന്ധികൾക്ക് ശേഷമുള്ള ശാന്തമായ കാലം — പ്രപഞ്ചത്തിൽ വിശ്വസിക്കുക.",
    "Reading Types": "വായനാ രീതികൾ",
    "Love & Relationship Spread": "പ്രണയ & ബന്ധ സ്പ്രെഡ്",
    "A 5-card spread revealing the current state of your love life, obstacles, and the path forward.": "പ്രണയ ജീവിത നില, തടസ്സങ്ങൾ, ഭാവി എന്നിവ വ്യക്തമാക്കുന്ന 5 കാർഡുകൾ അടങ്ങിയ സ്പ്രെഡ്.",
    "Career & Finance Spread": "കരിയർ & ധനകാര്യ സ്പ്രെഡ്",
    "A 3-card spread covering your current career situation, challenges, and the best action to take.": "നിലവിലെ തൊഴിൽ സാഹചര്യവും വെല്ലുവിളികളും സ്വീകരിക്കേണ്ട മികച്ച നടപടികളും കാട്ടുന്ന 3 കാർഡ് സ്പ്രെഡ്.",
    "Celtic Cross Spread": "കെൽറ്റിക് ക്രോസ് സമഗ്ര സ്പ്രെഡ്",
    "The most comprehensive 10-card spread providing a complete overview of your life situation.": "ജീവിതത്തിന്റെ സമഗ്ര വശങ്ങളും വിശദീകരിക്കുന്ന 10 കാർഡുകൾ അടങ്ങിയ വിശദമായ സ്പ്രെഡ്.",
    "Major Arcana Cards": "മേജർ അർക്കാന കാർഡുകൾ",
    "The Fool": "ദി ഫൂൾ (The Fool)",
    "The Magician": "ദി മജീഷ്യൻ (The Magician)",
    "The High Priestess": "ദി ഹൈ പ്രീസ്റ്റസ് (The High Priestess)",
    "The Empress": "ദി എംപ്രസ്സ് (The Empress)",
    "The Emperor": "ദി എംപറേർ (The Emperor)",
    "The Hierophant": "ദി ഹൈറോഫന്റ് (The Hierophant)",
    "The Lovers": "ദി ലവേഴ്സ് (The Lovers)",
    "The Chariot": "ദി ചാരിയറ്റ് (The Chariot)",
    "Decode the numbers of your destiny": "ജനന തീയതിയിലെ സംഖ്യാ രഹസ്യങ്ങൾ മനസ്സിലാക്കുക",
    "Numerology is the ancient science of numbers and their divine influence on human life. Every number carries a unique vibration that shapes your personality, destiny, and life path.": "സംഖ്യകളുടെ ദിവ്യ സ്വാധീനം വ്യക്തമാക്കുന്ന പുരാതന ശാസ്ത്രമാണ് സംഖ്യാശാസ്ത്രം. ഓരോ സംഖ്യയും നിങ്ങളുടെ വ്യക്തിത്വത്തെയും ഭാഗ്യത്തെയും സ്വാധീനിക്കുന്നു.",
    "Calculate Your Numbers": "നിങ്ങളുടെ സംഖ്യകൾ കണ്ടെത്തുക",
    "Date of Birth (DD/MM/YYYY)": "ജനന തീയതി (തീയതി/മാസം/വർഷം)",
    "Calculate My Numbers": "എന്റെ സംഖ്യ കണക്കാക്കുക",
    "Core Numbers": "പ്രധാന സംഖ്യകൾ",
    "Life Path Number": "ലൈഫ് പാത്ത് നമ്പർ (ജീവിത പാത)",
    "Derived from your birth date, this is the most important number — it reveals your life's purpose and the path you are meant to walk.": "ജനന തീയതിയിൽ നിന്ന് ലഭിക്കുന്ന പ്രധാന സംഖ്യ — ഇത് നിങ്ങളുടെ ജീവിത ലക്ഷ്യത്തെയും നടക്കേണ്ട പാതയെയും വ്യക്തമാക്കുന്നു.",
    "Destiny Number": "ഡെസ്റ്റിനി നമ്പർ (ഭാഗ്യ സംഖ്യ)",
    "Calculated from your full birth name, this reveals your talents, abilities, and the goals you are destined to achieve.": "നിങ്ങളുടെ പൂർണ്ണ നാമത്തിൽ നിന്ന് കണക്കാക്കുന്ന സംഖ്യ — ഇത് നിങ്ങളുടെ കഴിവുകളെയും നേട്ടങ്ങളെയും സൂചിപ്പിക്കുന്നു.",
    "Soul Urge Number": "സോൾ അർജ് നമ്പർ (ആത്മാവിന്റെ ഇച്ഛ)",
    "Derived from the vowels in your name, this reveals your innermost desires, motivations, and what truly makes your soul happy.": "പേരിലെ സ്വരാക്ഷരങ്ങളിൽ നിന്ന് നിങ്ങളുടെ ആന്തരിക ആഗ്രഹങ്ങളെ വ്യക്തമാക്കുന്ന സംഖ്യ.",
    "Life Path": "ജീവിത പാത",
    "Destiny": "ഭാഗ്യം",
    "Muhurat": "ശുഭ മുഹൂർത്തം",
    "Auspicious timings for life events": "ശുഭ കാര്യങ്ങൾക്കുള്ള ഉത്തമ മുഹൂർത്തങ്ങൾ",
    "Muhurat is the Vedic science of selecting the most auspicious time for important life events. Starting any significant activity at the right cosmic moment ensures divine blessings and minimises obstacles.": "പ്രധാന കാര്യങ്ങൾക്കായി ഏറ്റവും അനുയോജ്യമായ സമയം തിരഞ്ഞെടുക്കുന്ന വൈദിക ശാസ്ത്രമാണ് മുഹൂർത്തം. ശുഭ മുഹൂർത്തത്തിൽ തുടങ്ങുന്ന കാര്യങ്ങൾക്ക് തടസ്സങ്ങൾ നീങ്ങി വിജയം ലഭിക്കും.",
    "Upcoming Auspicious Dates": "വരാനിരിക്കുന്ന ശുഭ മുഹൂർത്ത തീയതികൾ",
