export function translateStringWithDict(text: string, lang: AppLanguage): string {
  if (!text || typeof text !== 'string') return text;
  if (lang === 'English') return text;

  const map = TRANSLATIONS[lang];
  if (!map) return text;

  const leadWs = text.match(/^\s*/)?.[0] || '';
  const trailWs = text.match(/\s*$/)?.[0] || '';
  const trimmed = text.trim();
  if (!trimmed) return text;

  // 1. Direct exact dictionary match
  if (map[trimmed]) {
    return `${leadWs}${map[trimmed]}${trailWs}`;
  }

  // 2. Direct case-insensitive match
  const lowerTrimmed = trimmed.toLowerCase();
  for (const k in map) {
    if (k.toLowerCase() === lowerTrimmed) {
      return `${leadWs}${map[k]}${trailWs}`;
    }
  }

  // 3. Compounds with bullets " • " or " | " or " · "
  if (trimmed.includes(' • ') || trimmed.includes(' | ') || trimmed.includes(' · ')) {
    const delim = trimmed.includes(' • ') ? ' • ' : trimmed.includes(' | ') ? ' | ' : ' · ';
    const parts = trimmed.split(delim);
    const translatedParts = parts.map((part) => translateStringWithDict(part, lang));
    return `${leadWs}${translatedParts.join(delim)}${trailWs}`;
  }

  // 4. Prefix with colon (e.g. "Balance: ₹0", "Live Consultation: sharma", "Talk to AI Astrologer: Acharya")
  const colonMatch = trimmed.match(/^([^:\n]+):\s*(.*)$/);
  if (colonMatch) {
    const prefix = colonMatch[1].trim();
    const rest = colonMatch[2];
    const trPrefix = map[prefix] || map[prefix.toLowerCase()];
    if (trPrefix) {
      const trRest = rest ? translateStringWithDict(rest, lang) : '';
      return `${leadWs}${trPrefix}: ${trRest}${trailWs}`.trimEnd();
    }
  }

  // 5. Symbols & Emojis extraction (leading and trailing emojis/arrows/symbols)
  const symRegex = /^([\s\uD800-\uDBFF\uDC00-\uDFFF\u2600-\u27BF✦✨⭐💫❤️💼💰🏥🌿💍🪐📜📅🕯️🙏🌟★❋🎁🕉️🌐💳👨‍🔮⚡+🔐>➔↗›→]+)?(.*?)([\s\uD800-\uDBFF\uDC00-\uDFFF\u2600-\u27BF✦✨⭐💫❤️💼💰🏥🌿💍🪐📜📅🕯️🙏🌟★❋🎁🕉️🌐💳👨‍🔮⚡+🔐>➔↗›→!?.:]+)?$/u;
  const symMatch = trimmed.match(symRegex);
  if (symMatch && symMatch[2]) {
    const leadSym = symMatch[1] || '';
    const coreText = symMatch[2].trim();
    const trailSym = symMatch[3] || '';

    if (coreText && (leadSym || trailSym)) {
      if (map[coreText]) {
        return `${leadWs}${leadSym}${map[coreText]}${trailSym}${trailWs}`;
      }
      const lowerCore = coreText.toLowerCase();
      for (const k in map) {
        if (k.toLowerCase() === lowerCore) {
          return `${leadWs}${leadSym}${map[k]}${trailSym}${trailWs}`;
        }
      }
    }
  }

  // 6. Regex patterns for dynamic quantities, timings, and phrases
  // A. "Until 05:29 PM"
  const untilMatch = trimmed.match(/^Until\s+(.*)$/i);
  if (untilMatch) {
    const timeVal = untilMatch[1].trim();
    if (lang === 'Telugu') return `${leadWs}${timeVal} వరకు${trailWs}`;
    if (lang === 'Hindi') return `${leadWs}${timeVal} तक${trailWs}`;
    if (lang === 'Tamil') return `${leadWs}${timeVal} வரை${trailWs}`;
    if (lang === 'Kannada') return `${leadWs}${timeVal} ವರೆಗೆ${trailWs}`;
    if (lang === 'Malayalam') return `${leadWs}${timeVal} വരെ${trailWs}`;
  }

  // B. "1 Online" / "28 Online"
  const onlineMatch = trimmed.match(/^(\d+)\+?\s*Online$/i);
  if (onlineMatch) {
    const count = onlineMatch[1];
    if (lang === 'Telugu') return `${leadWs}${count} ఆన్‌లైన్${trailWs}`;
    if (lang === 'Hindi') return `${leadWs}${count} ऑनलाइन${trailWs}`;
    if (lang === 'Tamil') return `${leadWs}${count} ஆன்லைன்${trailWs}`;
    if (lang === 'Kannada') return `${leadWs}${count} ಆನ್‌ಲೈನ್${trailWs}`;
    if (lang === 'Malayalam') return `${leadWs}${count} ഓൺലൈൻ${trailWs}`;
  }

  // C. "₹25/min"
  const priceMatch = trimmed.match(/^(?:₹|Rs\.?)\s*(\d+)\s*\/\s*min$/i);
  if (priceMatch) {
    const amt = priceMatch[1];
    if (lang === 'Telugu') return `${leadWs}₹${amt}/నిమిషానికి${trailWs}`;
    if (lang === 'Hindi') return `${leadWs}₹${amt}/मिनट${trailWs}`;
    if (lang === 'Tamil') return `${leadWs}₹${amt}/நிமிடம்${trailWs}`;
    if (lang === 'Kannada') return `${leadWs}₹${amt}/ನಿಮಿಷಕ್ಕೆ${trailWs}`;
    if (lang === 'Malayalam') return `${leadWs}₹${amt}/മിനിറ്റ്${trailWs}`;
  }

  // D. "10+ Yrs" / "35+ Yrs"
  const yrsMatch = trimmed.match(/^(\d+)\+?\s*Yrs\.?$/i);
  if (yrsMatch) {
    const yrs = yrsMatch[1];
    if (lang === 'Telugu') return `${leadWs}${yrs}+ సంవత్సరాలు${trailWs}`;
    if (lang === 'Hindi') return `${leadWs}${yrs}+ वर्ष अनुभव${trailWs}`;
    if (lang === 'Tamil') return `${leadWs}${yrs}+ வருடங்கள்${trailWs}`;
    if (lang === 'Kannada') return `${leadWs}${yrs}+ ವರ್ಷಗಳು${trailWs}`;
    if (lang === 'Malayalam') return `${leadWs}${yrs}+ വർഷം${trailWs}`;
  }

  // E. "₹5 / prompt"
  const promptMatch = trimmed.match(/^(?:₹|Rs\.?)\s*(\d+)\s*\/\s*prompt$/i);
  if (promptMatch) {
    const amt = promptMatch[1];
    if (lang === 'Telugu') return `${leadWs}₹${amt} / ప్రశ్నకి${trailWs}`;
    if (lang === 'Hindi') return `${leadWs}₹${amt} / प्रश्न${trailWs}`;
    if (lang === 'Tamil') return `${leadWs}₹${amt} / கேள்விக்கு${trailWs}`;
    if (lang === 'Kannada') return `${leadWs}₹${amt} / ಪ್ರಶ್ನೆಗೆ${trailWs}`;
    if (lang === 'Malayalam') return `${leadWs}₹${amt} / ചോദ്യത്തിന്${trailWs}`;
  }

  // F. "Ask AI Astrologer about your Love"
  const askAboutMatch = trimmed.match(/^Ask AI Astrologer about your\s+(.*)$/i);
  if (askAboutMatch) {
    const topic = askAboutMatch[1].trim();
    const trTopic = map[topic] || topic;
    if (lang === 'Telugu') return `${leadWs}మీ ${trTopic} గురించి AI జ్యోతిష్యుడిని అడగండి${trailWs}`;
    if (lang === 'Hindi') return `${leadWs}अपने ${trTopic} के बारे में AI ज्योतिषी से पूछें${trailWs}`;
    if (lang === 'Tamil') return `${leadWs}உங்கள் ${trTopic} பற்றி AI ஜோதிடரிடம் கேளுங்கள்${trailWs}`;
    if (lang === 'Kannada') return `${leadWs}ನಿಮ್ಮ ${trTopic} ಬಗ್ಗೆ AI ಜ್ಯೋತಿಷಿಯನ್ನು ಕೇಳಿ${trailWs}`;
    if (lang === 'Malayalam') return `${leadWs}നിങ്ങളുടെ ${trTopic} സംബന്ധിച്ച് AI ജ്യോതിഷിയോട് ചോദിക്കുക${trailWs}`;
  }

  // G. "Love Horoscope"
  const horoMatch = trimmed.match(/^(\w+)\s+Horoscope$/i);
  if (horoMatch) {
    const topic = horoMatch[1].trim();
    const trTopic = map[topic] || topic;
    if (lang === 'Telugu') return `${leadWs}${trTopic} రాశిఫలం${trailWs}`;
    if (lang === 'Hindi') return `${leadWs}${trTopic} राशिफल${trailWs}`;
    if (lang === 'Tamil') return `${leadWs}${trTopic} ராசிபலன்${trailWs}`;
    if (lang === 'Kannada') return `${leadWs}${trTopic} ರಾಶಿಫಲ${trailWs}`;
    if (lang === 'Malayalam') return `${leadWs}${trTopic} രാശിഫലം${trailWs}`;
  }

  // H. "06:30 am Sunrise"
  const sunMoonMatch = trimmed.match(/^(\d{1,2}:\d{2}\s*(?:[ap]m|[AP]M)?)\s*(Sunrise|Sunset|Moonrise|Moonset)$/i);
  if (sunMoonMatch) {
    const timeVal = sunMoonMatch[1].trim();
    const event = sunMoonMatch[2].trim();
    const trEvent = map[event] || event;
    return `${leadWs}${timeVal} ${trEvent}${trailWs}`;
  }

  // 7. Punctuation stripped match
  const lastChar = trimmed[trimmed.length - 1];
  if ([':', '?', '!', '.', '…'].includes(lastChar)) {
    const withoutPunct = trimmed.slice(0, -1).trim();
    if (map[withoutPunct]) {
      return `${leadWs}${map[withoutPunct]}${lastChar}${trailWs}`;
    }
  }

  return text;
}

interface LanguageState {
  selectedLanguage: AppLanguage;
  hydrated: boolean;
  load: () => Promise<void>;
  setLanguage: (lang: AppLanguage) => Promise<void>;
  t: (key: string, fallback?: string) => string;
  translateText: (text: string) => string;
}

export const useLanguageStore = create<LanguageState>((set, get) => ({
  selectedLanguage: 'English',
  hydrated: false,

  load: async () => {
    try {
      const stored = await AsyncStorage.getItem(STORAGE_LANG_KEY);
      if (stored && TRANSLATIONS[stored as AppLanguage]) {
        set({ selectedLanguage: stored as AppLanguage, hydrated: true });
      } else {
        set({ hydrated: true });
      }
    } catch {
      set({ hydrated: true });
    }
  },

  setLanguage: async (lang) => {
    set({ selectedLanguage: lang });
    try {
      await AsyncStorage.setItem(STORAGE_LANG_KEY, lang);
    } catch {}
  },

  translateText: (text: string) => {
    const lang = get().selectedLanguage;
    if (lang === 'English') return text;
    return translateStringWithDict(text, lang);
  },

  t: (key: string, fallback?: string) => {
    const lang = get().selectedLanguage;
    if (lang === 'English') return fallback ?? key;
    const map = TRANSLATIONS[lang];
    if (map && map[key]) return map[key];
    if (fallback) {
      const trFallback = translateStringWithDict(fallback, lang);
      if (trFallback !== fallback) return trFallback;
    }
    const trKey = translateStringWithDict(key, lang);
    if (trKey !== key) return trKey;
    return fallback ?? key;
  },
}));

/** Convenient hook for instant translation reactivity */
export function useTranslation() {
  const selectedLanguage = useLanguageStore((s) => s.selectedLanguage);
  const t = useLanguageStore((s) => s.t);
  const translateText = useLanguageStore((s) => s.translateText);
  const setLanguage = useLanguageStore((s) => s.setLanguage);
  return { selectedLanguage, t, translateText, setLanguage };
}
